import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"威胁模型","description":"","frontmatter":{"title":"威胁模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/threat-model.md","filePath":"cs/threat-model.md","lastUpdated":1789023840000}'),c={name:"cs/threat-model.md"};function E(A,a,_,m,B,f){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="威胁模型" tabindex="-1">威胁模型 <a class="header-anchor" href="#威胁模型" aria-label="Permalink to &quot;威胁模型&quot;">​</a></h1><div class="epigraph"><p>先写清谁能看、谁能改、谁能停，再选机制；没有敌手的「安全」只是口号。</p><footer>—— 据 Anderson, Security Engineering；Shostack 对威胁建模的整理</footer></div><p><a href="/cs/cia-triad">上一课</a>钉死三轴。本课不重定义保密。缺口是：三轴要对<strong>哪一类敌手</strong>成立。能窃听链路的人，与能跑同机进程的人，与能改 DNS 的人，不是同一场考试。后课每一种密码与隔离，都默认你已经会说「不防谁」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CIA 没有量化对象：无界全能敌手下没有可用系统。缺口不是列举攻击名称，而是画一张图：资产、入口、信任边界、敌手能力（被动窃听、主动改包、恶意端点、物理接触）。<a href="/cs/http-tls-entry">TLS 入口</a>防的是链路上的被动者加部分主动者，不防已攻破的浏览器。OS 隔离防的是用户态越权，不防同用户的漏洞代码。</p><p>本课不引入 STRIDE 的商标式背诵，只用「伪造、篡改、否认、信息泄露、拒绝服务、越权」当检查清单。</p><p><span class="marginnote">Kerckhoffs：系统的安全性应落在密钥保密，而不是算法隐瞒。威胁模型里「敌手知道算法」是默认，不是悲观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清：要保护的资产（密钥、库中元组、签名私钥）；敌手在边界外还是内；失败时优先保哪一轴。然后才映射到后课机制。假设崩溃的 2PC 与假设拜占庭的共识不是同一模型——本栏不把拜占庭共识插入主干，只标明 2PC 不在那一模型里。</p>',9)),(e(),n(h,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASSET%5B%22%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20BND%5B%22%E4%BF%A1%E4%BB%BB%E8%BE%B9%E7%95%8C%22%5D%0A%20%20BND%20--%3E%20ADV%5B%22%E6%95%8C%E6%89%8B%E8%83%BD%E5%8A%9B%22%5D%0A%20%20ADV%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E5%88%B0%E6%9C%BA%E5%88%B6%22%5D%0A%20%20MAP%20--%3E%20SYM%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同一机制在不同模型下结论相反。加密在「只能看链路」下给保密；在「能看内存」下不够。完整性在「能改包」下要 MAC；在「能拿签名私钥」下要撤销与旋转。把模型写进设计，后课才不会把 TLS 当成「整机安全」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>威胁模型会过时：侧信道把「看不到内存」改成「能测时间」。本课承认模型是假设，不是物理定律。也不把渗透清单当模型：清单是测试，模型是规格。</p><p>信任边界画错（把同一主机上的进程当成外部敌手或相反）会让后课沙箱与 TLS 的分工错位。后课默认：谈到采用某种密码，先有敌手能力；对称加密服务的是共享密钥已安全分发的那一类场景。</p><p>写不清「不防谁」，后课公钥与沙箱都会被误读成全能。模型宁可窄而真，不要宽而假。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>Kerckhoffs：敌手知道算法，秘密在密钥与边界。</p></li><li><p>后课对称加密只服务「能看密文、没有密钥」这一档。</p></li><li><p>CIA 是轴；本课补敌手、边界、资产。</p></li><li><p>算法公开、密钥保密是默认假设。</p></li><li><p>共享密钥下的保密机制，下一课才讲。</p></li><li><p>出处：Anderson, <em>Security Engineering</em>；Kerckhoffs, 1883。</p></li></ul>',8))])}const T=i(c,[["render",E]]);export{S as __pageData,T as default};
